const fs = require('fs');
const readline = require('readline');

const readStep7TS = (b, o = 0) => new Date(441774000000 + b.readUInt32BE(o) + (b.readUInt16BE(o + 4) * 86400000));

const blktype = {
    0: 'UDT',
    8: 'OB',
    10: 'DB',
    11: 'SDB',
    12: 'FC',
    13: 'SFC',
    14: 'FB',
    15: 'SFB',
    27: 'VAT'
}

/**
 * Parses a MC7 Block
 * @param {Buffer} buf 
 * @param {boolean} withData Whether the data is included (as on block upload) or not (as on block info)
 * @param {number} [offset=0] offset on the buffer to look after the data 
 * @returns {MC7Block}
 */
function parseS7Block(buf, withData, offset = 0) {
    if (buf.length - offset < 36) throw new Error('Not enough bytes to parse MC7 block header');

    let ptr = offset;
    let magic = buf.readUInt16BE(ptr);
    ptr += 2;
    if (magic != 0x7070) throw new Error(`Unexpected MC7 block header magic [0x${magic.toString(16)}] != 0x7070`);

    let unknown1 = buf.readUInt8(ptr);
    ptr += 1;
    let _flags = buf.readUInt8(ptr);
    ptr += 1;

    let flagLinked = !!(_flags & 0x01);
    let flagStdBlock = !!(_flags & 0x02);
    let flagNonRetain = !!(_flags & 0x04);

    let language = buf.readUInt8(ptr);
    ptr += 1;
    let type = buf.readUInt8(ptr);
    ptr += 1;
    let number = buf.readUInt16BE(ptr);
    ptr += 2;
    let loadLength = buf.readUInt32BE(ptr);
    ptr += 4;
    let security = buf.readUInt32BE(ptr);
    ptr += 4;

    let codeChange = readStep7TS(buf, ptr);
    ptr += 6;
    let ifaceChange = readStep7TS(buf, ptr);
    ptr += 6;

    let lengthSSB = buf.readUInt16BE(ptr);
    ptr += 2;
    let lengthADD = buf.readUInt16BE(ptr);
    ptr += 2;
    let lengthLocalData = buf.readUInt16BE(ptr);
    ptr += 2;
    let lengthMC7 = buf.readUInt16BE(ptr);
    ptr += 2;

    let dataMC7, dataSSB, dataADD;
    if (withData) {
        if (buf.length - ptr - lengthMC7 - lengthSSB - lengthADD < 0) throw new Error('Not enough bytes to parse MC7 block data');

        dataMC7 = buf.slice(ptr, ptr + lengthMC7).toString('hex');
        ptr += lengthMC7;
        dataSSB = buf.slice(ptr, ptr + lengthSSB).toString('hex');
        ptr += lengthSSB;
        dataADD = buf.slice(ptr, ptr + lengthADD).toString('hex');
        ptr += lengthADD;
    }

    let author, family, name, version, checksum
    if (buf.length - ptr >= 28) {

        author = buf.toString('ascii', ptr, ptr + 8).replace(/\x00+$/, '');
        ptr += 8;
        family = buf.toString('ascii', ptr, ptr + 8).replace(/\x00+$/, '');
        ptr += 8;
        name = buf.toString('ascii', ptr, ptr + 8).replace(/\x00+$/, '');
        ptr += 8;

        let bVer = buf.readUInt8(ptr);
        ptr += 1;
        version = `${bVer >> 4}.${bVer & 0xf}`

        let unknown2 = buf.readUInt8(ptr);
        ptr += 1;

        checksum = buf.readUInt16BE(ptr);
        ptr += 2;
    }

    let blockName = `${blktype[type]}${number}`;

    return {
        blockName,
        flagLinked, flagStdBlock, flagNonRetain, language, type,
        number, loadLength, security, codeChange, ifaceChange, lengthSSB,
        lengthADD, lengthLocalData, lengthMC7, dataMC7, dataSSB, dataADD,
        author, family, name, version, checksum
    };
}

/**
 * 
 * @param {Buffer} buf
 * @returns {MC7Block}
 */
function parseBlockInfo(buf) {

    if (buf.length < 78) throw new Error('Not enough bytes to parse block info');

    let ptr = 0;
    let unknown1 = buf.readUInt16BE(ptr);
    ptr += 2;
    let infoLength = buf.readUInt16BE(ptr);
    ptr += 2;

    if (buf.length - ptr < infoLength) throw new Error(`Not enough bytes for info length, available [${buf.length}], needs [${infoLength}]`);

    let unknown2 = buf.readUInt16BE(ptr);
    ptr += 2;

    let blk = parseS7Block(buf, false, ptr);

    return blk;
}


async function parseBlocksFromFile(filename) {
    const rl = readline.createInterface({
        input: fs.createReadStream(filename),
        crlfDelay: Infinity
    });

    for await (const line of rl) {
        if (line.trim().length === 0) continue; // Ignora linhas vazias
        try {
            const buffer = Buffer.from(line.trim(), 'hex');
            const result = parseBlockInfo(buffer);
            console.dir(result, { depth: null });
        } catch (err) {
            console.error('Erro ao processar linha:', line, err.message);
        }
    }
}

// Exemplo de uso:
parseBlocksFromFile('blocks_hex.txt');